from collections import Counter

def find_components(grid, bg):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != bg and (r,c) not in visited:
                component = [(r,c)]
                stack = [(r,c)]
                while stack:
                    cr, cc = stack.pop()
                    if (cr,cc) in visited:
                        continue
                    visited.add((cr,cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == grid[cr][cc] and (nr,nc) not in visited:
                                component.append((nr,nc))
                                stack.append((nr,nc))
                components.append(component)

    return components

